sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	var request_sys_id = current.getValue('sys_id');

	if(request_sys_id){
		console.log("---in update----");
        var update_request = new GlideRecord('sn_lms_book_requests');
		update_request.addQuery("sys_id", request_sys_id);
		update_request.query();
        if (update_request.next()) {
			var currentDate = new GlideDate();
            update_request.requested_date = currentDate;
            update_request.user_id = gs.getUserID();
            update_request.status = 'pending';
			update_request.update();
        }
	}
})(current, previous);
